namespace InterlockExpeditions.Portal.Models;

/// <summary>Public editorial metadata contains no actual room or player records.</summary>
public sealed class Episode { public string Id { get; set; } = ""; public string Version { get; set; } = ""; public string Title { get; set; } = ""; public string Tagline { get; set; } = ""; public string Introduction { get; set; } = ""; public int Minutes { get; set; } public int Stations { get; set; } }
public sealed class EpisodeList { public List<Episode> Episodes { get; set; } = []; }
public sealed class HostAccount { public string Id { get; set; } = ""; public string Alias { get; set; } = ""; public long CreatedAt { get; set; } }
public sealed class AccountResult { public HostAccount? Account { get; set; } public bool Premium { get; set; } public string? RecoveryKey { get; set; } public string? Warning { get; set; } }
public sealed class RoomList { public List<Room> Rooms { get; set; } = []; public bool Premium { get; set; } }
/// <summary>Server timer values are milliseconds; a browser clock never authorizes progress.</summary>
public sealed class Room { public string Id { get; set; } = ""; public string Title { get; set; } = ""; public string EpisodeId { get; set; } = ""; public string EpisodeVersion { get; set; } = ""; public string Status { get; set; } = "lobby"; public string? Outcome { get; set; } public int StageIndex { get; set; } public int Revision { get; set; } public int Capacity { get; set; } public long RemainingMs { get; set; } public long ServerNow { get; set; } public long? PausedAt { get; set; } public int Mistakes { get; set; } public long CreatedAt { get; set; } public long? StartedAt { get; set; } public long? FinishedAt { get; set; } }
public sealed class CrewPlayer { public string Id { get; set; } = ""; public string Alias { get; set; } = ""; public string Role { get; set; } = ""; public long JoinedAt { get; set; } public long SeenAt { get; set; } }
public sealed class RoomEvent { public string Kind { get; set; } = ""; public string Message { get; set; } = ""; public long CreatedAt { get; set; } }
public sealed class RoomControl { public Room Room { get; set; } = new(); public string EpisodeTitle { get; set; } = ""; public int StageCount { get; set; } public string CurrentStation { get; set; } = ""; public string Invitation { get; set; } = ""; public List<CrewPlayer> Players { get; set; } = []; public List<RoomEvent> Events { get; set; } = []; }
/// <summary>Private role projection; another crew's card and objective configuration are not included.</summary>
public sealed class PlayState { public Room Room { get; set; } = new(); public CrewPlayer Player { get; set; } = new(); public string PlayerKey { get; set; } = ""; public string EpisodeTitle { get; set; } = ""; public string Introduction { get; set; } = ""; public string Ending { get; set; } = ""; public int StageCount { get; set; } public Station? Station { get; set; } public List<CrewPlayer> Players { get; set; } = []; public List<RoomEvent> Events { get; set; } = []; }
public sealed class Station { public string Id { get; set; } = ""; public string Kind { get; set; } = ""; public string Title { get; set; } = ""; public string Scene { get; set; } = ""; public string Clue { get; set; } = ""; public string Hint { get; set; } = ""; public Machine Machine { get; set; } = new(); }
public sealed class CrewChecks { public bool Signal { get; set; } public bool Engine { get; set; } }
public sealed class ArmedTerminals { public long Signal { get; set; } public long Engine { get; set; } }
public sealed class CradleLoads { public int Left { get; set; } public int Right { get; set; } public bool Loaded { get; set; } }
/// <summary>Typed state for the six implemented controls; absent station-specific fields have harmless display defaults.</summary>
public sealed class Machine { public CrewChecks Checked { get; set; } = new(); public string Feedback { get; set; } = ""; public int Attempts { get; set; } public int[] Dials { get; set; } = [0, 0, 0]; public string Route { get; set; } = "north"; public int[] Inputs { get; set; } = [0, 0, 0]; public int[] Bypass { get; set; } = [0, 0, 0]; public int[] Outputs { get; set; } = [0, 0, 0]; public int[] Wiring { get; set; } = []; public int Position { get; set; } public List<int> Visited { get; set; } = []; public bool Cargo { get; set; } public int Gate { get; set; } public int Steps { get; set; } public int[] Walls { get; set; } = []; public int CargoCell { get; set; } = -1; public int ExitCell { get; set; } = 15; public int GateCell { get; set; } = -1; public string[] Placements { get; set; } = ["off", "off", "off"]; public int Ballast { get; set; } public CradleLoads Loads { get; set; } = new(); public int Limit { get; set; } public int BallastLimit { get; set; } public int Inner { get; set; } public int Outer { get; set; } public ArmedTerminals Armed { get; set; } = new(); public int WindowMs { get; set; } }
/// <summary>Device-private recovery capability. It must never appear in an invitation, public report or log.</summary>
public sealed class PlayerIdentity { public string RoomId { get; set; } = ""; public string Id { get; set; } = ""; public string Key { get; set; } = ""; }
